def ligand_features(system, transform):
    factory = ChemicalFeatures.BuildFeatureFactory(str(Path(RDConfig.RDDataDir)/'BaseFeatures.fdef'))
    feats = []
    for f in factory.GetFeaturesForMol(system['mol']):
        if f.GetFamily() not in FAMILIES: continue
        ids = list(f.GetAtomIds()); orig = [system['active'][i] for i in ids]
        pos = system['coords'][orig].mean(axis=0)
        pos = (pos-transform[0]) @ transform[2]+transform[1]
        feats.append({'family':FAMILIES[f.GetFamily()],'rdkit_family':f.GetFamily(),
                      'atoms':orig,'coords':pos.tolist()})
    return sorted(feats,key=lambda f:(f['family'],f['atoms']))

def receptor_features(ref):
    top = ref['top']; names=top['ATOM_NAME']; types=top['AMBER_ATOM_TYPE']
    ids = set(ref['keys'].values()); neigh = {i:[] for i in range(len(names))}
    for i,j in ref['bonds']: neigh[i].append(j); neigh[j].append(i)
    points=[]
    def add(fam, atoms):
        points.append({'family':fam,'atoms':sorted(atoms),'coords':ref['coords'][atoms].mean(axis=0).tolist()})
    for i in sorted(ids):
        e = element(types[i],names[i])
        hs = [j for j in neigh[i] if element(types[j],names[j])=='H']
        if e in ['N','O'] and hs: add('HD',[i])
        if e=='O' and not hs: add('HA',[i])
        if e=='C' and types[i] not in ['C','c']: add('HP',[i])
    graph=nx.Graph(); graph.add_nodes_from(i for i in ids if types[i] in ['CA','ca'])
    graph.add_edges_from((i,j) for i,j in ref['bonds'] if i in graph and j in graph)
    for ring in nx.cycle_basis(graph):
        if len(ring)==6: add('AR',ring)
    heavy=ref['coords'][[i for i in ref['active'] if element(types[i],names[i])!='H']]
    for p in points:
        p['selection_distance']=float(np.linalg.norm(heavy-np.array(p['coords']),axis=1).min())
        p['atom_names']=[names[i] for i in p['atoms']]
    points.sort(key=lambda p:(p['selection_distance'],p['family'],p['atoms']))
    return points[:4],len(points)

def align(system,ref):
    keys=sorted(set(system['keys']) & set(ref['keys']))
    a=system['coords'][[system['keys'][k] for k in keys]]
    b=ref['coords'][[ref['keys'][k] for k in keys]]
    ac,bc=a.mean(axis=0),b.mean(axis=0)
    u,_,vt=np.linalg.svd((a-ac).T@(b-bc)); corr=np.eye(3)
    corr[-1,-1]=np.linalg.det(u@vt); rot=u@corr@vt
    rms=float(np.sqrt(np.mean(np.sum(((a-ac)@rot+bc-b)**2,axis=1))))
    return (ac,bc,rot),{'common_protein_heavy_atoms':len(keys),'rmsd_angstrom':rms}

def receptor_points(S, ligxyz, fixed_res=None):
    prot = [i for i in range(S['n']) if S['rl'][S['res'][i]] not in ('LIG', 'WAT', 'Na+', 'Cl-', 'HOH')]
    typ = {i: S['types'][i] for i in prot}
    pts = features(S, prot, typ, False)
    out = []
    for lab, x, ref in pts:
        ids = ref if isinstance(ref, tuple) else (ref,)
        if fixed_res is not None:
            if any(S['res'][k] in fixed_res for k in ids): out.append((lab, x, ref))
        elif np.min(np.linalg.norm(ligxyz[:, None, :]-S['xyz'][list(ids)][None], axis=2)) <= 5.0: out.append((lab, x, ref))
    return out
def solve(lp, rp, eps, epss, tau):
    V = [(a, b) for a in range(len(lp)) for b in range(len(rp))]
    hb = {'HD', 'HA'}
    ev = [epss if (lp[a][0] in hb and rp[b][0] in hb) else eps for a, b in V]
    G = nx.Graph()
    for k, (a, b) in enumerate(V): G.add_node(k, w=int(round(1e4*W[lp[a][0]][rp[b][0]])))
    LX = np.array([p[1] for p in lp]); RX = np.array([p[1] for p in rp])
    dl = np.linalg.norm(LX[:, None]-LX[None], axis=2); dr = np.linalg.norm(RX[:, None]-RX[None], axis=2)
    for k1 in range(len(V)):
        a1, b1 = V[k1]
        for k2 in range(k1+1, len(V)):
            a2, b2 = V[k2]
            if (tau+ev[k1]+ev[k2]) - abs(dl[a1, a2]-dr[b1, b2]) > 0: G.add_edge(k1, k2)
    # exact MWC = max-weight independent set on the complement graph, solved as a MILP (HiGHS), gap reported
    w = np.array([G.nodes[k]['w'] for k in range(len(V))], float)
    non = [(i, j) for i in range(len(V)) for j in range(i+1, len(V)) if not G.has_edge(i, j)]
    r = np.repeat(np.arange(len(non)), 2); c = np.array(non).ravel()
    A = coo_matrix((np.ones(len(c)), (r, c)), shape=(len(non), len(V)))
    t = time.time()
    sol = milp(-w, constraints=LinearConstraint(A, -np.inf, 1), integrality=np.ones(len(V)), bounds=Bounds(0, 1),
               options=dict(time_limit=float(sys.argv[4]) if len(sys.argv) > 4 else 10.0, mip_rel_gap=0.0))
    C = [k for k in range(len(V)) if sol.x is not None and sol.x[k] > 0.5]
    assert all(G.has_edge(a, b) for a, b in itertools.combinations(C, 2))
    w = sum(G.nodes[k]['w'] for k in C)
    return dict(W=w/1e4, status=sol.status, message=sol.message, dual_bound=None if sol.mip_dual_bound is None else -sol.mip_dual_bound/1e4, gap=sol.mip_gap, nV=len(V), nE=G.number_of_edges(), clique_size=len(C), seconds=round(time.time()-t, 2),
                clique=sorted(f"{lp[V[k][0]][0].lower()}{V[k][0]}-{rp[V[k][1]][0]}{V[k][1]}" for k in C))

def rings6(idx, bonds, ok):
    out = set()
    for a in idx:
        def dfs(path):
            if len(path) == 6:
                if path[0] in bonds[path[-1]]: out.add(frozenset(path))
                return
            for b in bonds[path[-1]]:
                if ok(b) and b not in path and b > path[0]: dfs(path+[b])
        dfs([a])
    return [sorted(r) for r in out]
def features(S, atoms, typ, ligand):
    """atoms: candidate indices; typ: dict index->type for those atoms (dummies already removed)."""
    E = {i: elem(typ[i]) for i in atoms}
    nb = {i: [j for j in S['bonds'][i] if j in typ] for i in atoms}
    nH = {i: sum(E.get(j) == 'H' for j in nb[i]) for i in atoms}
    pts = []
    for i in atoms:
        e, t = E[i], typ[i]
        if e in ('N', 'O') and nH[i] >= 1: pts.append(('HD', S['xyz'][i], i))
        if e == 'O' or (ligand and t in ('nb', 'nc', 'nd')) or (not ligand and t == 'NB'): pts.append(('HA', S['xyz'][i], i))
        if e in ('Cl', 'Br') or (e == 'S' and not ligand): pts.append(('HP', S['xyz'][i], i))
        if e == 'C' and nH[i] == 3 and all(E[j] in ('C', 'H') for j in nb[i]) and (t in ('c3', 'CT')): pts.append(('HP', S['xyz'][i], i))
    arom = (lambda b: b in typ and typ[b] == 'ca') if ligand else (lambda b: b in typ and typ[b] in AROM_P)
    for r in rings6([i for i in atoms if arom(i)], S['bonds'], arom):
        pts.append(('AR', S['xyz'][r].mean(0), tuple(r)))
    return pts
